import UIKit
final class PatientListViewController: UIViewController { var viewModel: PatientListViewModel!; private var items:[Patient] = []; private let table = UITableView(frame:.zero,style:.insetGrouped); private let stateView = StateView(); override func viewDidLoad(){super.viewDidLoad(); title = "Patients"; configure(); bind(); viewModel.load()}; private func configure(){view.backgroundColor = .systemGroupedBackground; table.dataSource = self; table.delegate = self; table.register(UITableViewCell.self,forCellReuseIdentifier:"Cell"); view.addSubview(table); table.pinToEdges(of:view); view.addSubview(stateView); stateView.pinToEdges(of:view); stateView.backgroundColor = .systemGroupedBackground}; private func bind(){viewModel.onState = { [weak self] state in guard let self else{return}; switch state{case .idle:break;case .loading:stateView.showLoading();case .loaded(let patients):items = patients;stateView.hide();table.reloadData();case .failed(let m):stateView.showMessage(m)}}} }
extension PatientListViewController:UITableViewDataSource,UITableViewDelegate{func tableView(_ tableView:UITableView,numberOfRowsInSection section:Int)->Int{items.count};func tableView(_ tableView:UITableView,cellForRowAt indexPath:IndexPath)->UITableViewCell{let c = UITableViewCell(style:.subtitle,reuseIdentifier:nil);let p = items[indexPath.row];var cfg = c.defaultContentConfiguration();cfg.text = p.name;cfg.secondaryText = "\(p.condition) • Age \(p.age) • Last visit \(p.lastVisit)";cfg.image = UIImage(systemName:"cross.case.fill");c.contentConfiguration = cfg;c.accessoryType = .disclosureIndicator;return c}}
